/* @autogenerated */
export type BulkEditFieldType = 'text' | 'number' | 'boolean' | 'enum' | 'relation';
export type BulkEditOperation =
  | 'replace'
  | 'prefix'
  | 'suffix'
  | 'add'
  | 'multiply'
  | 'clear'
  | 'setTrue'
  | 'setFalse'
  | 'setNull';

export interface BulkEditField<T> {
  readonly name: keyof T & string;
  readonly label: string;
  readonly type: BulkEditFieldType;
  readonly optional?: boolean;
  readonly options?: readonly { readonly value: string; readonly label: string }[];
}

export interface BulkEditChange {
  readonly field: string;
  readonly operation: BulkEditOperation;
  readonly value: string | number | boolean | null;
}

export function applyBulkEdit<T>(item: T, changes: readonly BulkEditChange[]): T {
  const result = { ...item } as Record<string, unknown>;
  for (const change of changes) {
    const current = result[change.field];
    if (
      ['prefix', 'suffix', 'add', 'multiply'].includes(change.operation) &&
      (current === undefined || current === null)
    ) {
      continue;
    }
    switch (change.operation) {
      case 'clear':
        result[change.field] = undefined;
        break;
      case 'setNull':
        result[change.field] = null;
        break;
      case 'setTrue':
        result[change.field] = true;
        break;
      case 'setFalse':
        result[change.field] = false;
        break;
      case 'replace':
        result[change.field] = change.value;
        break;
      case 'prefix':
        result[change.field] = `${change.value}${current ?? ''}`;
        break;
      case 'suffix':
        result[change.field] = `${current ?? ''}${change.value}`;
        break;
      case 'add':
        result[change.field] = Number(current) + Number(change.value);
        break;
      case 'multiply':
        result[change.field] = Number(current) * Number(change.value);
        break;
    }
  }
  return result as T;
}
